// Menger Carve - color. STATIC (no t/u_time). Runs INSIDE shadeSurface().
// The outer faces keep u_col1; the tunnel walls are colored by their SCALE: the
// big ones sink toward u_col2, the small ones stay lighter, so the generations of
// the sponge read at a glance. The engine's AO darkens the depths.
// In scope: pModel, n_model. Dock colors: u_col1 = outer faces, u_col2 = big tunnels.

float DENSITY = 2.4 * max(E, 0.05);   // slider E   // MUST match the displacement
int   LEVELS  = int(clamp(floor(2.0 + F + 0.5), 1.0, 4.0));   // slider F
vec3  ACCENT = vec3(0.95, 0.55, 0.25);   // warm tint of the middle generation

vec3 mp = pModel * DENSITY;
float tunnel = -1e9;
float lvl = 0.0;
float sc = 1.0;
for (int m = 0; m < 4; m++) {
    if (m >= LEVELS) break;
    vec3 a = mod(mp * sc, 2.0) - 1.0;
    sc *= 3.0;
    vec3 rr = abs(1.0 - 3.0 * abs(a));
    float da = max(rr.x, rr.y);
    float db = max(rr.y, rr.z);
    float dc = max(rr.z, rr.x);
    float c = (min(da, min(db, dc)) - 1.0) / sc;
    if (c > tunnel) { tunnel = c; lvl = float(m); }
}

// 1 on the walls of a tunnel (tunnel ~ 0 there), 0 on the outer faces (tunnel < 0).
// The band is wider than the marcher's hit tolerance (~0.007 sponge units at the
// default size): narrower, the walls came out sprinkled with face-colored dots.
float inTunnel = smoothstep(-0.016, -0.007, tunnel);
float gen = lvl / max(float(LEVELS - 1), 1.0);   // 0 = big tunnels, 1 = smallest

vec3 face = ubuf.u_col1 * (0.92 + 0.08 * smoothstep(-0.12, -0.01, tunnel));
vec3 inner = mix(ubuf.u_col2, ubuf.u_col1 * 0.8, gen);
inner = mix(inner, ACCENT * ubuf.u_col1, 0.35 * (1.0 - abs(2.0 * gen - 1.0)));

textureCol = mix(face, inner, inTunnel);

