// Menger Carve - relief (displacement). STATIC (no t/u_time). Runs INSIDE map().
// The object is intersected with an endless Menger sponge: square tunnels at
// several scales, each a third of the previous one, running right THROUGH the
// object (look through the holes: the background shows). The sponge is the classic
// distance bound (iq): at each level space is folded into cells of size 2/3^level
// and a cross of three square tunnels is removed from every cell.
// In scope: d_surf, p, pModel.
//
// SPEED. A tunnel can raise the field by at most 1/(3 DENSITY): farther OUTSIDE than
// REACH the intersection returns d_surf unchanged, so skipping the sponge there gives
// EXACTLY the same field. Rays that miss the object pay one comparison.
// (A version with a floor at a fixed depth was tried: where the floor met the walls
// of the finer tunnels it showed rows of dark speckles. Through-holes have no floor.)

float DENSITY = 2.4 * max(E, 0.05);                  // slider E // sponge cells per unit [1.5 .. 8]
int   LEVELS  = int(clamp(floor(2.0 + F + 0.5), 1.0, 4.0));   // slider F // generations: F = 1 -> 3
float ROUND   = 0.004;   // edge rounding (model units): keeps the normals clean   [0 .. 0.01]

float REACH = 1.0 / (3.0 * DENSITY) + ROUND + 0.01;

if (d_surf < REACH) {
    vec3 mp = pModel * DENSITY;
    float tunnel = -1e9;   // > 0 inside a tunnel (sponge units)
    float sc = 1.0;
    for (int m = 0; m < 4; m++) {
        if (m >= LEVELS) break;
        vec3 a = mod(mp * sc, 2.0) - 1.0;
        sc *= 3.0;
        vec3 rr = abs(1.0 - 3.0 * abs(a));
        float da = max(rr.x, rr.y);
        float db = max(rr.y, rr.z);
        float dc = max(rr.z, rr.x);
        tunnel = max(tunnel, (min(da, min(db, dc)) - 1.0) / sc);
    }
    tunnel /= DENSITY;   // back to model units

    // object AND sponge: smooth max over ROUND (perfectly sharp edges make the
    // normals, sampled 0.005 apart, flip across them -> speckles)
    float hi = clamp(0.5 - 0.5 * (d_surf - tunnel) / ROUND, 0.0, 1.0);
    d_surf = mix(d_surf, tunnel, hi) + ROUND * hi * (1.0 - hi);
}
